local FanMaker = {}
local PRODUCTS = {
    palm_fan = { name = "Palmino pahljačo", woodCost = 1, time = 1, cost = 5, happiness = 1, description = "Preprosta pahljača." },
    folding_fan = { name = "Zložljiva pahljača", woodCost = 2, clothCost = 1, time = 3, cost = 30, happiness = 3, description = "Zložljiva s tkanino." },
    painted_fan = { name = "Poslikana pahljača", woodCost = 2, parchmentCost = 1, paintCost = 1, time = 7, cost = 80, happiness = 5, prestige = 3, description = "Z ročno poslikavo." },
    silk_fan = { name = "Svilena pahljača", woodCost = 2, silkCost = 2, time = 5, cost = 100, happiness = 6, prestige = 5, description = "Svilena pahljača." },
    jeweled_fan = { name = "Draguljarna pahljača", woodCost = 3, silkCost = 2, jewelCost = 1, goldCost = 1, time = 14, cost = 400, happiness = 10, prestige = 15, description = "Z drago kamen in zlatom." },
    ceremonial_fan = { name = "Ceremonialna pahljača", goldCost = 2, silkCost = 3, jewelCost = 2, time = 20, cost = 800, happiness = 15, prestige = 25, description = "Za kraljevske slovesnosti." },
}
local BUILDINGS = {
    workshop = { name = "Pahljačarska delavnica", cost = { gold = 150, wood = 100 }, upkeep = 3, qualityBonus = 5 },
    fan_studio = { name = "Pahljačarski atelje", cost = { gold = 600, wood = 200, stone = 100 }, upkeep = 15, qualityBonus = 15 },
    painting_room = { name = "Slikarska soba", cost = { gold = 1000, wood = 200, stone = 200 }, upkeep = 25, qualityBonus = 20 },
    royal_fan_maker = { name = "Kraljevski pahljačar", cost = { gold = 3000, wood = 400, stone = 600, gold = 50 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
FanMaker.woodStock = 15; FanMaker.clothStock = 5; FanMaker.parchmentStock = 5; FanMaker.paintStock = 3; FanMaker.silkStock = 4; FanMaker.jewelStock = 2; FanMaker.goldStock = 3
FanMaker.productStock = {}; FanMaker.buildings = {}; FanMaker.maker = nil; FanMaker.activeMaking = {}; FanMaker.totalProducts = 0; FanMaker.dayTimer = 0
function FanMaker.init() FanMaker.woodStock=15; FanMaker.clothStock=5; FanMaker.parchmentStock=5; FanMaker.paintStock=3; FanMaker.silkStock=4; FanMaker.jewelStock=2; FanMaker.goldStock=3; FanMaker.productStock={}; FanMaker.buildings={}; FanMaker.maker=nil; FanMaker.activeMaking={}; FanMaker.totalProducts=0; FanMaker.dayTimer=0; print("[FanMaker] Royal Fan Maker & Fan Painter System initialized (6 products, 4 buildings)") end
function FanMaker.hireMaker(n,s) s=s or math.random(35,80); local c=200+s*4; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FanMaker.maker={name=n or ("Pahljačar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pahljačar najet: %s (spretnost: %d)",FanMaker.maker.name,s),"success") end; return true end
function FanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FanMaker.build(id) local ok,e=FanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FanMaker.getQualityBonus() local b=0; for _,bd in ipairs(FanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.clothCost and FanMaker.clothStock<(d.clothCost or 0) then return false,"Premalo blaga" end; if d.parchmentCost and FanMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.paintCost and FanMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silkCost and FanMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.jewelCost and FanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if d.goldCost and FanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #FanMaker.buildings==0 then return false,"Potrebna delavnica" end; if not FanMaker.maker then return false,"Potreben pahljačar" end; return true end
function FanMaker.make(pt) local ok,e=FanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FanMaker.woodStock=FanMaker.woodStock-d.woodCost end; if d.clothCost then FanMaker.clothStock=FanMaker.clothStock-d.clothCost end; if d.parchmentCost then FanMaker.parchmentStock=FanMaker.parchmentStock-d.parchmentCost end; if d.paintCost then FanMaker.paintStock=FanMaker.paintStock-d.paintCost end; if d.silkCost then FanMaker.silkStock=FanMaker.silkStock-d.silkCost end; if d.jewelCost then FanMaker.jewelStock=FanMaker.jewelStock-d.jewelCost end; if d.goldCost then FanMaker.goldStock=FanMaker.goldStock-d.goldCost end; local t=d.time; if FanMaker.maker then t=math.max(1,t-math.floor(FanMaker.maker.skill/12)) end; table.insert(FanMaker.activeMaking,{id="fan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function FanMaker.completeMaking(m) local q=1.0+(FanMaker.getQualityBonus()/100); if FanMaker.maker then q=q+(FanMaker.maker.skill/200) end; q=math.min(2.0,q); FanMaker.productStock[m.productType]=(FanMaker.productStock[m.productType] or 0)+1; FanMaker.totalProducts=FanMaker.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if FanMaker.maker then FanMaker.maker.itemsMade=FanMaker.maker.itemsMade+1; if math.random()<0.15 then FanMaker.maker.skill=math.min(100,FanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pahljača izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function FanMaker.update(dt) if not _G.state then return end; FanMaker.dayTimer=FanMaker.dayTimer+dt; if FanMaker.dayTimer>=30 then FanMaker.dayTimer=0; for i=#FanMaker.activeMaking,1,-1 do local m=FanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FanMaker.completeMaking(m); table.remove(FanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FanMaker.maker then tu=tu+5 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FanMaker.getStats() return {woodStock=FanMaker.woodStock,silkStock=FanMaker.silkStock,jewelStock=FanMaker.jewelStock,productStock=FanMaker.productStock,numBuildings=#FanMaker.buildings,hasMaker=FanMaker.maker~=nil,makerName=FanMaker.maker and FanMaker.maker.name or "—",makerSkill=FanMaker.maker and FanMaker.maker.skill or 0,activeMaking=#FanMaker.activeMaking,totalProducts=FanMaker.totalProducts} end
return FanMaker
